var rows=new System.Collections.Generic.List<object>();
foreach(var setting in UnityEditor.EditorBuildSettings.scenes){
 if(!setting.enabled || setting.path.Contains("MainMenu"))continue;
 var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(setting.path, UnityEditor.SceneManagement.OpenSceneMode.Additive);
 try{
 var cols=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Collider2D>(true)).ToArray();
 var data=new System.Collections.Generic.List<object>();
 foreach(var c in cols){if(!c.enabled || !c.gameObject.activeInHierarchy || c.isTrigger)continue;
 var mesh=c.CreateMesh(true,true); if(mesh==null)continue;
 data.Add(new {name=c.name,type=c.GetType().Name,layer=c.gameObject.layer,body=c.attachedRigidbody==null?"static":c.attachedRigidbody.bodyType.ToString(),vertices=mesh.vertices.Select(v=>new[]{v.x,v.y}).ToArray(),triangles=mesh.triangles});UnityEngine.Object.DestroyImmediate(mesh);
 }
 var level=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<CampaignLevel>(true)).FirstOrDefault();
 rows.Add(new {scene=setting.path,spawn=level==null?null:new[]{level.initialSpawn.x,level.initialSpawn.y},route=level==null||level.route==null?null:level.route.Select(v=>new[]{v.x,v.y}).ToArray(),colliders=data});
 }finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);}
}
System.IO.File.WriteAllText("scripts/clearance-20261112/geometry.json",Codely.Newtonsoft.Json.JsonConvert.SerializeObject(rows));
UnityEngine.Debug.Log("Exported "+rows.Count+" scenes without saving or replacing active scene");
